<script setup>
import {marinaOfficeOptions} from '../../data/marinaOffices.js'
import { computed,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import { printReport } from '../../lib/exports.js'
import { clone,incidentOptions,officeOptions,display } from './common.js'
const props=defineProps({kind:{type:String,required:true}}),store=useDemo(),route=useRoute()
const search=ref(''),eventFilter=ref(route.query.eventId || ''),dialog=ref(false),draft=ref({}),error=ref(''),removeDialog=ref(false),file=ref(null),section=ref('identity')
const kind=computed(()=>props.kind),isVessel=computed(()=>kind.value==='vessels'),isEvidence=computed(()=>kind.value==='evidence')
const title=computed(()=>isVessel.value?'Vessel registry':isEvidence.value?'Evidence register':'Owners and operators')
const description=computed(()=>isVessel.value?'Maintain vessel identity and particulars while retaining historical involvement snapshots.':isEvidence.value?'Link typed source metadata to an incident, investigation revision or case.':'Keep owner, operator and company roles, aliases and contact information distinct.')
const allowed=computed(()=>isEvidence.value ? store.can('report') || store.can('review') || store.can('investigate') || store.can('enforce') : isVessel.value ? store.can('report') || store.can('investigate') : store.can('investigate'))
const rows=computed(()=>store.visibleRecords(kind.value).filter(r=>(!isEvidence.value || !eventFilter.value || r.eventId===eventFilter.value) && Object.values(r).filter(v=>typeof v==='string' || Array.isArray(v)).join(' ').toLowerCase().includes((search.value || '').toLowerCase())))
const columns=computed(()=>isVessel.value ? [{name:'name',label:'Vessel identity',field:'name',align:'left',sortable:true},{name:'type',label:'Service / rig',field:'type',align:'left'},{name:'grossTonnage',label:'GT',field:r=>display(r.grossTonnage),align:'right',sortable:true},{name:'owner',label:'Owner / operator',field:'owner',align:'left'},{name:'status',label:'Registration',field:'registrationStatus',align:'left'},{name:'actions',label:'',field:'id'}] : isEvidence.value ? [{name:'name',label:'Document / source',field:'name',align:'left',sortable:true},{name:'type',label:'Document type',field:'type',align:'left',sortable:true},{name:'eventId',label:'Related incident',field:r=>store.getEvent(r.eventId)?.ref || 'Not linked',align:'left'},{name:'uploadedAt',label:'Recorded',field:r=>r.uploadedAt ? r.uploadedAt.slice(0,10) : 'Unknown',align:'left',sortable:true},{name:'status',label:'Availability',field:'status',align:'left'},{name:'actions',label:'',field:'id'}] : [{name:'name',label:'Party / aliases',field:'name',align:'left',sortable:true},{name:'type',label:'Party role',field:'type',align:'left',sortable:true},{name:'email',label:'Contact',field:'email',align:'left'},{name:'address',label:'Address',field:'address',align:'left'},{name:'status',label:'Status',field:r=>r.active?'active':'inactive',align:'left'},{name:'actions',label:'',field:'id'}])
const sourceCategories={type:'shipType',rigType:'rigType',hull:'hullMaterial',sizeClass:'sizeClass',classificationSociety:'classificationSociety',enginePowerUnit:'powerUnit'}
const registryReferenceKeys=['flag','owner','operator','operationType','registrationStatus','portOfRegistry','homeportPlace','buildPlace','sternType','engineMake']
const registryReferences=field=>[...new Set(store.visibleRecords('vessels').map(vessel=>vessel[field]).filter(Boolean))]
const vesselSections=[
 {name:'identity',label:'Identity',fields:[['name','Name of Ship/Vessel *'],['formerNames','Former names / aliases (comma separated)'],['officialNumber','Official Number'],['imoNumber','IMO Number'],['callSign','Call Sign'],['operationType','Type of Operation'],['portOfRegistry','Port of Registry'],['homeportPlace','Homeport (place)'],['registrationStatus','Registration status',['Registered','Unregistered','Pending verification','Unknown']],['rigType','Rig Type'],['type','Type of Ship'],['flag','Flag State'],['homeport','Homeport Office','office'],['cpc','CPC Issuing Office','office']]},
 {name:'construction',label:'Build and class',fields:[['grossTonnage','Gross Tonnage (GT)','number'],['netTonnage','Net Tonnage (NT)','number'],['deadweight','Deadweight (tonnes)','number'],['length','Registered Length (m)','number'],['breadth','Breadth (m)','number'],['depth','Depth (m)','number'],['yearBuilt','Year Built','number'],['buildPlace','Place Built'],['hull','Hull Material'],['sizeClass','Size Classification'],['classificationSociety','Classification Society'],['sternType','Stern type']]},
 {name:'machinery',label:'Machinery',fields:[['engineCount','Number of Engines','number'],['engineMake','Engine make / model'],['enginePower','Engine Power','number'],['enginePowerUnit','Power Unit (hp/kW)',['kW','HP','Unknown']]]},
 {name:'ownership',label:'Owner and operator',fields:[['owner','Owner / company'],['operator','Operator / company'],['ownerContact','Owner contact'],['operatorAddress','Business Address'],['masterName','Name of Master/Captain'],['masterLicense','Master licence / competency reference'],['officeId','Responsible office','office']]},
]
const relatedEvents=computed(()=>{if(isEvidence.value)return store.visibleEvents.value.filter(e=>e.id===draft.value.eventId || e.evidenceIds?.includes(draft.value.id));const aliases=isVessel.value ? [draft.value.name,...String(draft.value.formerNames || '').split(',')] : [draft.value.name,...(draft.value.aliases || [])];return store.visibleEvents.value.filter(e=>e.vessels?.some(v=>isVessel.value ? (v.id===draft.value.id || aliases.some(a=>a && a.trim().toLowerCase()===v.name?.toLowerCase())) : aliases.some(a=>a && [v.owner,v.operator].includes(a))))})
const relatedVessels=computed(()=>!isVessel.value && !isEvidence.value ? store.visibleRecords('vessels').filter(v=>[draft.value.name,...(draft.value.aliases || [])].some(a=>a && [v.owner,v.operator].includes(a))) : [])
const reports=computed(()=>store.visibleRecords('reports').filter(r=>r.eventId===draft.value.eventId))
const cases=computed(()=>store.can('enforce') ? store.visibleRecords('cases').filter(c=>c.eventId===draft.value.eventId) : [])
const aliasText=ref('')
watch(()=>store.visibleRecords(kind.value).map(r=>r.id).join('|'),()=>{if(draft.value?.id && !store.visibleRecords(kind.value).some(r=>r.id===draft.value.id)){dialog.value=false;draft.value={};error.value='This record is unavailable in your current account scope.'}})
watch(()=>props.kind,()=>{dialog.value=false;search.value='';eventFilter.value=route.query.eventId || ''})
function edit(r){error.value='';if(r){const visible=store.visibleRecords(kind.value).find(item=>item.id===r.id);if(!visible){dialog.value=false;draft.value={};error.value='This record is unavailable in your current account scope.';return}r=visible;}file.value=null;section.value='identity';draft.value=r ? clone(r) : isVessel.value ? {...store.newVessel(),ownerId:store.currentUser.value?.id,officeId:store.currentUser.value?.officeId} : isEvidence.value ? {name:'',eventId:eventFilter.value || '',type:'Source report',sourceRef:'',url:'',mime:'',size:null,uploadedBy:store.currentUser.value?.id,uploadedAt:new Date().toISOString(),notes:'',status:'reference_only',reportId:'',caseId:''} : {name:'',type:'company',address:'',email:'',phone:'',aliases:[],active:true};if(Array.isArray(draft.value.formerNames))draft.value.formerNames=draft.value.formerNames.join(', ');aliasText.value=(draft.value.aliases || []).join(', ');dialog.value=true}
function selectedFile(value){if(!value)return;draft.value.name ||=value.name;draft.value.mime=value.type || 'application/octet-stream';draft.value.size=value.size;draft.value.notes=[draft.value.notes,`Local selection: ${value.name}. File contents are not uploaded or retained.`].filter(Boolean).join('\n');draft.value.status='reference_only'}
function save(){try{if(!allowed.value)throw Error('Staff editing permission required.');if(!draft.value.name?.trim())throw Error('A name is required.');const data=clone(draft.value);if(isVessel.value){for(const k of ['grossTonnage','netTonnage','deadweight','length','breadth','depth','yearBuilt','engineCount','enginePower']){const v=data[k];data[k]=v==='' || v===undefined || v===null ? null : Number(v);if(data[k]!==null && (!Number.isFinite(data[k]) || data[k]<0))throw Error(`${k} must be a non-negative number or unknown.`)}for(const k of ['yearBuilt','engineCount'])if(data[k]!==null && !Number.isInteger(data[k]))throw Error(`${k} must be a whole number.`)}else if(!isEvidence.value)data.aliases=aliasText.value.split(',').map(a=>a.trim()).filter(Boolean);if(isEvidence.value){data.size=data.size==='' || data.size==null ? null : Number(data.size);if(data.size!==null && (!Number.isInteger(data.size) || data.size<0))throw Error('File size must be a non-negative whole number or unknown.')}if(isEvidence.value && data.url && !/^https?:\/\//i.test(data.url))throw Error('Source links must use https:// or http://. Leave the link blank for local metadata.');const result=data.id ? store.update(kind.value,data.id,data) : store.add(kind.value,data);if(isEvidence.value && result.eventId){const incident=store.getEvent(result.eventId);if(incident && (store.can('report',incident) || store.can('review',incident) || store.can('investigate',incident)) && !(incident.evidenceIds || []).includes(result.id))store.saveEvent({...incident,evidenceIds:[...(incident.evidenceIds || []),result.id]})}dialog.value=false;error.value=''}catch(e){error.value=e.message}}
function remove(){try{if(isEvidence.value && store.visibleRecords('reports').some(r=>r.status==='issued' && r.evidenceIds?.includes(draft.value.id)))throw Error('This source is linked to an issued report revision and must be retained.');store.remove(kind.value,draft.value.id);removeDialog.value=false;dialog.value=false;error.value=''}catch(e){error.value=e.message;removeDialog.value=false}}
function preview(){const d=draft.value;printReport({title:d.name,subtitle:'Evidence metadata preview · Demonstration / fictional data',metadata:{incident:store.getEvent(d.eventId)?.ref,documentType:d.type,availability:d.status},sections:[{title:'Source record',content:`Reference: ${display(d.sourceRef)}\nSource link: ${display(d.url)}\nMIME: ${display(d.mime)}\nSize bytes: ${display(d.size)}\nRecorded: ${display(d.uploadedAt)}\n${d.notes || ''}`},{title:'Local document behavior',content:'This preview presents registered metadata. Selected file bytes are not uploaded or retained; production evidence storage requires backend integration.'}]})}
</script>
<template><div class="page-wrap"><PageHeader :title="title" :subtitle="description"><template #actions><q-btn v-if="allowed" color="primary" no-caps icon="add" :label="isVessel?'Add vessel':isEvidence?'Register evidence':'Add owner / operator'" @click="edit()"/></template></PageHeader><q-banner v-if="error && !dialog" rounded class="bg-red-1 text-negative q-mb-md">{{error}}</q-banner><div class="panel toolbar-row q-mb-md"><q-input v-model="search" outlined dense clearable :label="isVessel?'Search names, aliases or identifiers':'Search names, references or contacts'" style="min-width:300px"><template #prepend><q-icon name="search"/></template></q-input><q-select v-if="isEvidence" v-model="eventFilter" clearable outlined dense :options="incidentOptions(store.visibleEvents.value)" emit-value map-options label="Related incident" style="min-width:260px"/><q-space/><span class="muted">{{rows.length}} records</span></div><div class="panel"><q-table flat :rows="rows" :columns="columns" row-key="id" :pagination="{rowsPerPage:10,sortBy:'name'}"><template #body-cell-name="p"><q-td :props="p"><a href="#" class="record-link" @click.prevent="edit(p.row)">{{p.row.name}}</a><div class="muted">{{isVessel ? `Official ${p.row.officialNumber || 'unknown'} · IMO ${p.row.imoNumber || 'unknown'}` : isEvidence ? p.row.sourceRef : p.row.aliases?.join(' · ')}}</div></q-td></template><template #body-cell-type="p"><q-td :props="p">{{p.row.type || 'Unknown'}}<div class="muted" v-if="isVessel">{{p.row.rigType || 'Rig unknown'}}</div></q-td></template><template #body-cell-owner="p"><q-td :props="p">{{p.row.owner || 'Owner unknown'}}<div class="muted">{{p.row.operator || 'Operator unknown'}}</div></q-td></template><template #body-cell-status="p"><q-td :props="p"><StatusBadge :status="isVessel ? p.row.registrationStatus || 'unknown' : isEvidence ? p.row.status : p.row.active?'active':'inactive'"/></q-td></template><template #body-cell-actions="p"><q-td :props="p"><q-btn flat no-caps color="primary" :label="allowed?'View / edit':'View'" @click="edit(p.row)"/></q-td></template></q-table></div>
<q-dialog v-model="dialog"><q-card style="width:940px;max-width:96vw"><q-card-section><div class="toolbar-row"><div class="text-h6">{{draft.id ? draft.name : isVessel?'New vessel':isEvidence?'Register evidence':'New owner / operator'}}</div><q-space/><q-btn flat round dense icon="close" v-close-popup aria-label="Close"/></div><q-banner v-if="error" rounded class="bg-red-1 text-negative q-my-md">{{error}}</q-banner><q-form @submit="save" class="q-mt-md">
<template v-if="isVessel"><q-tabs v-model="section" align="left" active-color="primary" mobile-arrows outside-arrows><q-tab v-for="s in vesselSections" :key="s.name" :name="s.name" :label="s.label" no-caps/><q-tab name="history" label="Historical involvement" no-caps/></q-tabs><q-tab-panels v-model="section" animated><q-tab-panel v-for="s in vesselSections" :key="s.name" :name="s.name"><div class="form-grid"><template v-for="f in s.fields" :key="f[0]"><MarinaSelect v-if="sourceCategories[f[0]]" v-model="draft[f[0]]" :category="sourceCategories[f[0]]" :label="f[1]" :readonly="!allowed"/><MarinaSelect v-else-if="registryReferenceKeys.includes(f[0])" v-model="draft[f[0]]" :options="registryReferences(f[0])" allow-other :label="f[1]" :readonly="!allowed"/><q-select v-else-if="Array.isArray(f[2])" v-model="draft[f[0]]" outlined clearable :options="f[2]" :label="f[1]" :readonly="!allowed"/><q-select v-else-if="f[2]==='office'" v-model="draft[f[0]]" outlined clearable :options="marinaOfficeOptions(store.state.offices,draft[f[0]],f[0])" emit-value map-options :label="f[1]" :readonly="!allowed"/><q-input v-else v-model="draft[f[0]]" outlined :type="f[2] || 'text'" :label="f[1]" :min="f[2]==='number'?0:undefined" :step="f[2]==='number'?'any':undefined" :readonly="!allowed"/></template></div><p class="muted q-mb-none">Blank numeric particulars remain unknown. Historical incident vessel snapshots retain their recorded particulars.</p></q-tab-panel><q-tab-panel name="history"><q-list separator><q-item v-for="e in relatedEvents" :key="e.id" clickable :to="`/admin/incidents/${e.id}`"><q-item-section>{{e.ref}} · {{e.type}}<q-item-label caption>{{e.date || 'Date unknown'}} · {{e.place}}</q-item-label></q-item-section><q-item-section side><StatusBadge :status="e.status"/></q-item-section></q-item></q-list><p class="muted" v-if="!relatedEvents.length">No involvement matched this vessel identity or its aliases.</p></q-tab-panel></q-tab-panels></template>
<div v-else-if="isEvidence" class="form-grid"><q-input v-model="draft.name" outlined label="Document / source name *" class="span-2" :readonly="!allowed"/><q-select v-model="draft.type" outlined :options="['Source report','Spot report','Photograph','Witness statement','Certificate','Inspection record','SCO / order','Decision','Correspondence','Other']" label="Document type" :readonly="!allowed"/><q-select v-model="draft.status" outlined :options="['reference_only','available']" label="Source availability" :readonly="!allowed"/><q-select v-model="draft.eventId" @update:model-value="draft.reportId='';draft.caseId=''" outlined clearable :options="incidentOptions(store.visibleEvents.value)" emit-value map-options label="Related incident" :readonly="!allowed"/><q-select v-model="draft.reportId" outlined clearable :options="reports.map(r=>({label:`MAIC ${r.type} · revision ${r.revision}`,value:r.id}))" emit-value map-options label="Related report revision" :readonly="!allowed"/><q-select v-if="store.can('enforce')" v-model="draft.caseId" outlined clearable :options="cases.map(c=>({label:c.caseNumber,value:c.id}))" emit-value map-options label="Related enforcement case" :readonly="!allowed"/><q-input v-model="draft.sourceRef" outlined label="Source / document reference" :readonly="!allowed"/><q-input v-model="draft.url" outlined label="Source URL (optional, http / https)" :readonly="!allowed"/><q-input v-model="draft.mime" outlined label="MIME type" :readonly="!allowed"/><q-input v-model="draft.size" outlined type="number" min="0" label="Size in bytes (blank = unknown)" :readonly="!allowed"/><q-file v-if="allowed" v-model="file" @update:model-value="selectedFile" outlined clearable label="Select local file metadata" class="span-2"><template #prepend><q-icon name="attach_file"/></template></q-file><p class="muted span-2 q-my-none">File selection records metadata in this browser. File contents are not uploaded or retained. Availability describes the source, not storage on a server.</p><q-input v-model="draft.notes" outlined type="textarea" label="Description, provenance and access notes" class="span-2" :readonly="!allowed"/></div>
<template v-else><div class="form-grid"><q-input v-model="draft.name" outlined label="Party / company name *" :readonly="!allowed"/><q-select v-model="draft.type" outlined :options="['owner','operator','company']" label="Party role" :readonly="!allowed"/><q-input v-model="aliasText" outlined label="Aliases (comma separated)" class="span-2" :readonly="!allowed"/><q-input v-model="draft.address" outlined type="textarea" label="Address" class="span-2" :readonly="!allowed"/><q-input v-model="draft.email" outlined type="email" label="Email" :readonly="!allowed"/><q-input v-model="draft.phone" outlined label="Phone" :readonly="!allowed"/><q-toggle v-model="draft.active" label="Active directory entry" :disable="!allowed"/></div><div class="section-title q-mt-lg">Linked vessel identities</div><p v-for="v in relatedVessels" :key="v.id">{{v.name}} · {{v.owner===draft.name?'Owner':'Operator'}}</p><p v-if="!relatedVessels.length" class="muted">No vessel owner / operator name or alias matches this party.</p><div class="section-title q-mt-lg">Incident involvement</div><q-btn v-for="e in relatedEvents" :key="e.id" flat color="primary" no-caps :label="e.ref" :to="`/admin/incidents/${e.id}`"/></template>
<div class="toolbar-row q-mt-lg"><q-btn v-if="allowed && draft.id" flat no-caps color="negative" label="Delete record" @click="removeDialog=true"/><q-btn v-if="isEvidence" outline no-caps icon="print" label="Preview metadata" @click="preview"/><q-space/><q-btn flat no-caps label="Close" v-close-popup/><q-btn v-if="allowed" color="primary" no-caps label="Save record" type="submit"/></div></q-form></q-card-section></q-card></q-dialog><q-dialog v-model="removeDialog"><q-card style="max-width:480px"><q-card-section><div class="text-h6">Delete local directory record?</div><p>Historical incident snapshots and the audit trail remain. Evidence referenced by issued revisions must be retained.</p></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn color="negative" no-caps label="Delete" @click="remove"/></q-card-actions></q-card></q-dialog>
</div></template>
